#pragma once

// Test fixtures: known PCM, and the two container formats that carry it.
//
// The roadmap asks for fixtures generated by a helper rather than committed as
// binaries, and for a WAV and a FLAC of the *same* known ramp decoded and
// compared sample for sample. Both encoders here are written out byte by byte
// rather than driven through a library, which is the point: if the reference
// bytes came out of FFmpeg's own encoder, a decoder that misread the 24-bit
// alignment could be matched by an encoder that miswrote it and the test would
// pass on a stream nothing else can play.
//
// The FLAC encoder is a real FLAC stream and not a shortcut. It uses VERBATIM
// subframes -- the subframe type that stores samples unencoded -- so it needs
// no predictor, no residual coding and no entropy coder, and every bit of it
// is decided here. The file is larger than a real encoder's and decodes
// identically, which is all a fixture has to do.

#include "audio/AudioFormat.h"

#include <cstddef>
#include <cstdint>
#include <span>
#include <vector>

namespace multiroomtest {

// One known signal, before any container has touched it.
struct PcmFixture
{
    uint32_t sampleRate = 0;
    uint16_t channels = 0;

    // 16 or 24. The significant bits, not the container size -- this is the
    // depth the encoders write and the depth the decoder has to give back.
    uint32_t bits = 0;

    uint32_t frames = 0;

    // Interleaved, one entry per sample, right-aligned and sign-extended into
    // int32 whatever `bits` is. That is the shape MATP's int16 and int24in32
    // both hold, so a comparison against a decoded buffer is a comparison of
    // values rather than of layouts.
    std::vector<int32_t> samples;
};

// A signal built to make an alignment error obvious rather than subtle: it
// opens with zero, plus and minus one, and both extremes of the range, then
// walks the whole range in steps large enough that neighbouring samples share
// no leading bits. A ramp of small increments would survive a shift of eight
// looking merely quiet.
PcmFixture makeRamp(uint32_t sampleRate, uint16_t channels, uint32_t bits, uint32_t frames);

// RIFF/WAVE, PCM: int16 little-endian, or three packed bytes for 24.
std::vector<std::byte> encodeWav(const PcmFixture& fixture);

// A FLAC stream of VERBATIM subframes. blockFrames is the block size; the last
// block is whatever is left.
std::vector<std::byte> encodeFlac(const PcmFixture& fixture, uint32_t blockFrames = 4096);

// Reads decoded PCM back as right-aligned, sign-extended values, so a test
// compares against PcmFixture::samples directly.
std::vector<int32_t> readSamples(std::span<const std::byte> bytes,
                                 multiroom::AudioFormat::SampleType type);

} // namespace multiroomtest
